        LinearLayout menu=new LinearLayout(this);menu.setOrientation(LinearLayout.VERTICAL);menu.setPadding(dp(20),dp(16),dp(20),dp(20));menu.setBackgroundColor(p.bg);menu.addView(text("Аккаунты FunPay",20,p.text));
