        for(int i=0;i<accounts.length();i++){JSONObject account=accounts.optJSONObject(i);String id=account.optString("uid"),name=account.optString("name","Аккаунт FunPay"),balance=account.optString("balance");LinearLayout row=new LinearLayout(this);row.setGravity(Gravity.CENTER_VERTICAL);row.setPadding(0,dp(14),0,dp(14));row.setMinimumHeight(dp(48));row.addView(new AvatarView(this,name,account.optString("avatar"),p),new LinearLayout.LayoutParams(dp(44),dp(44)));LinearLayout copy=new LinearLayout(this);copy.setOrientation(LinearLayout.VERTICAL);copy.setPadding(dp(12),0,dp(12),0);copy.addView(text(name+(uid.equals(id)?" · выбран":""),15,p.text));copy.addView(text(balance.isEmpty()?"Баланс ещё не загружен":balance,12,p.muted));row.addView(copy,new LinearLayout.LayoutParams(0,-2,1));row.setClickable(true);row.setFocusable(true);row.setTag("account-"+id);row.setContentDescription("Переключиться: "+name);row.setOnClickListener(v->{dialog.dismiss();if(uid.equals(id))return;generation++;loading=false;drafts.clear();compose=null;chatId="";chatSearch="";settingsCategory="";page="chats";try{AccountSwitch.open(this,id,()->{profileChecked=0;render();refreshProfile();});}catch(Exception e){alert(e.getMessage());}});menu.addView(row);}
        menu.addView(action("Добавить аккаунты по QR",()->{dialog.dismiss();startActivityForResult(new Intent(this,WelcomeActivity.class).putExtra("configure",true),11);}));
        menu.addView(action("Добавить аккаунт через FunPay",()->{dialog.dismiss();site("/account/login",true);}));
