    void chats(){
        LinearLayout controls=new LinearLayout(this);controls.setGravity(Gravity.CENTER_VERTICAL);EditText search=input("Поиск в чатах",chatSearch,false);search.setContentDescription("Поиск по имени или сообщению");search.setTag("chat-search");search.setMinHeight(dp(48));controls.addView(search,new LinearLayout.LayoutParams(0,-2,1));controls.addView(chatIconButton("refresh","Обновить список чатов",()->requestChatRefresh(true)));body.addView(controls);
        LinearLayout filters=new LinearLayout(this);filters.setPadding(0,dp(10),0,dp(8));Button all=chatFilter("Все",!unreadChatsOnly),unread=chatFilter("Непрочитанные",unreadChatsOnly);filters.addView(all,new LinearLayout.LayoutParams(0,-2,1));LinearLayout.LayoutParams up=new LinearLayout.LayoutParams(0,-2,1);up.setMarginStart(dp(8));filters.addView(unread,up);body.addView(filters);
        chatRefreshState=text("",11,p.muted);chatRefreshState.setAccessibilityLiveRegion(View.ACCESSIBILITY_LIVE_REGION_POLITE);body.addView(chatRefreshState);
        chatListView=new LinearLayout(this);chatListView.setTag("chat-list");chatListView.setOrientation(LinearLayout.VERTICAL);body.addView(chatListView);
        search.addTextChangedListener(new android.text.TextWatcher(){public void beforeTextChanged(CharSequence value,int start,int count,int after){}public void onTextChanged(CharSequence value,int start,int before,int count){chatSearch=value.toString();drawChatList();}public void afterTextChanged(android.text.Editable value){}});
        all.setOnClickListener(v->{unreadChatsOnly=false;styleChatFilter(all,true);styleChatFilter(unread,false);drawChatList();});unread.setOnClickListener(v->{unreadChatsOnly=true;styleChatFilter(all,false);styleChatFilter(unread,true);drawChatList();});drawChatList();requestChatRefresh(false);
    }
    void drawChatList(){
        if(chatListView==null)return;int scroll=scroller.getScrollY();chatListView.removeAllViews();List<FunPayClient.Chat> rows=chatLists.get(prefs.uid());
        if(rows==null){chatListView.addView(text("Загружаю чаты…",13,p.muted));return;}
        String query=chatSearch.toLowerCase(Locale.ROOT);for(var chat:rows){if(unreadChatsOnly&&!chat.unread)continue;if(!(chat.name+" "+chat.text).toLowerCase(Locale.ROOT).contains(query))continue;chatListView.addView(ChatViews.contact(this,chat,()->{compose=null;chatId=chat.id;chatName=chat.name;chatAvatar=chat.avatar;render();}));View divider=new View(this);divider.setBackgroundColor(p.line);LinearLayout.LayoutParams rule=new LinearLayout.LayoutParams(-1,dp(1));rule.setMarginStart(dp(63));chatListView.addView(divider,rule);}
        if(chatListView.getChildCount()==0)chatListView.addView(text(unreadChatsOnly?"Нет непрочитанных чатов":"Чаты не найдены",14,p.muted));scroller.post(()->scroller.scrollTo(0,scroll));
    }
    String chatSignature(Object rows){StringBuilder signature=new StringBuilder();if(rows instanceof List<?> list)for(Object item:list){if(item instanceof FunPayClient.Chat chat)signature.append(chat.id).append('|').append(chat.name).append('|').append(chat.text).append('|').append(chat.time).append('|').append(chat.avatar).append('|').append(chat.status).append('|').append(chat.unread);else if(item instanceof FunPayClient.Message message)signature.append(message.author).append('|').append(message.text).append('|').append(message.time).append('|').append(message.own).append('|').append(message.system).append('|').append(message.status);signature.append('\n');}return signature.toString();}
    void drawChatMessages(boolean initial){
        if(chatMessagesView==null)return;List<FunPayClient.Message> rows=chatHistories.get(prefs.uid()+":"+chatId);if(rows==null){chatMessagesView.addView(text("Загружаю сообщения…",13,p.muted));return;}
        int oldY=scroller.getScrollY();boolean bottom=body.getHeight()-scroller.getHeight()-oldY<dp(72);chatMessagesView.removeAllViews();for(var message:rows)chatMessagesView.addView(ChatViews.message(this,message));if(rows.isEmpty())chatMessagesView.addView(text("Сообщений пока нет. Вложения и полная история доступны на FunPay.",13,p.muted));
        Integer saved=initial?chatScrolls.get(prefs.uid()+":"+chatId):null;scroller.post(()->{if(saved!=null)scroller.scrollTo(0,saved);else if(initial||bottom)scroller.fullScroll(View.FOCUS_DOWN);else scroller.scrollTo(0,oldY);});
    }
    void requestChatRefresh(boolean manual){
        if(disposed||!page.equals("chats")||chatRefreshing||loading||!connected())return;
        if(!foreground&&!manual)return;
        final String uid=prefs.uid(),id=chatId;final int viewGeneration=generation;chatRefreshing=true;
        if(chatRefreshState!=null&&manual)chatRefreshState.setText("Обновляю…");
        executor.execute(()->{try{FunPayClient client=new FunPayClient(this);if(!uid.equals(client.uid))throw new IOException("Аккаунт изменился");Object rows;boolean cached=client.ensureAuth();try{rows=loadRefresh(client,id);}catch(Exception first){if(!cached)throw first;client.forgetAuth();client=new FunPayClient(this);client.authenticate();rows=loadRefresh(client,id);}
            final Object loaded=rows;handler.post(()->{chatRefreshing=false;refreshFailures=0;if(disposed||!uid.equals(prefs.uid()))return;if(!chatDataAccount.equals(uid)){chatLists.clear();chatHistories.clear();chatScrolls.clear();chatDataAccount=uid;}if(id.isEmpty()){@SuppressWarnings("unchecked") List<FunPayClient.Chat> values=(List<FunPayClient.Chat>)loaded;chatLists.put(uid,values);}else{@SuppressWarnings("unchecked") List<FunPayClient.Message> values=(List<FunPayClient.Message>)loaded;if(chatHistories.size()>20)chatHistories.clear();chatHistories.put(uid+":"+id,values);}
                if(!foreground||viewGeneration!=generation||!page.equals("chats")||!id.equals(chatId))return;String next=chatSignature(loaded);if(!next.equals(chatSignature)){chatSignature=next;if(id.isEmpty())drawChatList();else drawChatMessages(false);}if(chatRefreshState!=null)chatRefreshState.setText("");
            });
        }catch(Exception error){handler.post(()->{chatRefreshing=false;if(refreshFailures<10)refreshFailures++;if(disposed||!foreground||viewGeneration!=generation||!uid.equals(prefs.uid()))return;if(chatRefreshState!=null)chatRefreshState.setText("Не удалось обновить · повторим автоматически");});}});
    }
    Object loadRefresh(FunPayClient client,String id) throws Exception {
        if(!id.isEmpty())return client.messages(id);
        List<FunPayClient.Chat> chats=client.chats();try{client.enrichOrders(chats);}catch(Exception ignored){}return chats;
    }
