    void rules(){
        JSONObject ar=prefs.replies();JSONArray rules=ar.optJSONArray("keywords");if(rules==null)rules=new JSONArray();final JSONArray values=rules;
        LinearLayout layout=new LinearLayout(this);layout.setPadding(dp(20),0,dp(20),0);layout.setOrientation(LinearLayout.VERTICAL);EditText key=input("Ключевое слово","",false),reply=input("Ответ","",true);layout.addView(key);layout.addView(reply);Switch contains=new Switch(this);contains.setText("Искать вхождение, а не полное совпадение");contains.setChecked(true);layout.addView(contains);
        new AlertDialog.Builder(this).setTitle("Правил: "+values.length()).setView(layout).setPositiveButton("Добавить",(d,w)->{try{values.put(new JSONObject().put("keyword",key.getText().toString().trim()).put("response",reply.getText().toString().trim()).put("matchMode",contains.isChecked()?"contains":"exact"));JSONObject a=prefs.replies();a.put("keywords",values);prefs.replies(ru.funpay.tools.Settings.cleanReplies(a));}catch(Exception e){alert(e.getMessage());}}).setNeutralButton("Удалить правило",(d,w)->{String[] names=new String[values.length()];for(int i=0;i<names.length;i++)names[i]=values.optJSONObject(i).optString("keyword");new AlertDialog.Builder(this).setTitle("Удалить").setItems(names,(dd,index)->{values.remove(index);try{JSONObject a=prefs.replies();a.put("keywords",values);prefs.replies(a);}catch(Exception ignored){}}).show();}).setNegativeButton("Закрыть",null).show();
    }
    void pending(){JSONObject state=prefs.state(prefs.uid()),jobs=state.optJSONObject("pending");if(jobs==null||jobs.length()==0){alert(prefs.status()+"\nНезавершённых ответов нет");return;}List<String> ids=new ArrayList<>();jobs.keys().forEachRemaining(ids::add);new AlertDialog.Builder(this).setTitle("Ответы требуют проверки").setItems(ids.toArray(new String[0]),(d,i)->new AlertDialog.Builder(this).setTitle("Чат "+ids.get(i)).setMessage("Откройте чат и проверьте, дошёл ли ответ. Автоматически повторять неизвестную отправку приложение не будет.").setPositiveButton("Открыть",(dd,w)->site("/chat/?node="+ids.get(i),false)).setNeutralButton("Убрать из очереди",(dd,w)->{jobs.remove(ids.get(i));prefs.state(prefs.uid(),state);}).setNegativeButton("Закрыть",null).show()).show();}
    @Override protected void onActivityResult(int code,int result,Intent data){super.onActivityResult(code,result,data);guardChatAccount();if(result!=RESULT_OK){if(code==10)render();return;}if(code==10){render();return;}if(data==null||data.getData()==null)return;Uri uri=data.getData();try{if(code==22){StringBuilder key=new StringBuilder();try(Reader input=new InputStreamReader(getContentResolver().openInputStream(uri),java.nio.charset.StandardCharsets.UTF_8)){char[] buffer=new char[1024];int count;while((count=input.read(buffer))!=-1){key.append(buffer,0,count);if(key.length()>4096)throw new IOException("Ключ больше 4 КБ");}}CloudSync.connect(this,key.toString());render();handler.removeCallbacks(refreshCloud);handler.post(refreshCloud);}else if(code==20){StringBuilder raw=new StringBuilder();try(Reader in=new InputStreamReader(getContentResolver().openInputStream(uri),"UTF-8")){char[] b=new char[4096];int n;while((n=in.read(b))!=-1){raw.append(b,0,n);if(raw.length()>2*1024*1024)throw new IOException("Файл больше 2 МБ");}}JSONObject cfg=ru.funpay.tools.Settings.decode(raw.toString());new AlertDialog.Builder(this).setTitle("Импортировать настройки?").setMessage("Настройки текущего аккаунта будут заменены. Фон остановится. Секреты и данные сессии не импортируются; неподдерживаемые функции не запускаются.").setPositiveButton("Импортировать",(d,w)->{stopService(new Intent(this,PresenceService.class));PeriodicPresence.schedule(this,false);prefs.save(cfg);prefs.applyImportedAppearance(cfg);render();}).setNegativeButton("Отмена",null).show();}else if(code==21){try(OutputStream out=getContentResolver().openOutputStream(uri)){out.write(prefs.encode().getBytes(java.nio.charset.StandardCharsets.UTF_8));}Toast.makeText(this,"Настройки экспортированы",Toast.LENGTH_SHORT).show();}}catch(Exception e){alert(e.getMessage());}}
    @Override protected void onResume(){super.onResume();if(!connected()){startActivity(new Intent(this,WelcomeActivity.class));finish();return;}guardChatAccount();foreground=true;if(prefs!=null&&(!page.equals("chats")||root==null||!renderedAppearance.equals(appearanceSignature())))render();handler.removeCallbacks(refreshChats);handler.post(refreshChats);AppUpdates.check(this,false);refreshProfile();CloudSyncWorker.schedule(this);handler.removeCallbacks(refreshCloud);handler.post(refreshCloud);}
    @Override protected void onPause(){foreground=false;handler.removeCallbacks(refreshChats);handler.removeCallbacks(refreshCloud);super.onPause();}
    @Override protected void onDestroy(){disposed=true;handler.removeCallbacksAndMessages(null);executor.shutdown();syncExecutor.shutdownNow();if(accountsDialog!=null)accountsDialog.dismiss();if(alertDialog!=null)alertDialog.dismiss();super.onDestroy();}
